contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 dep1, uint256 dep2) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (dep1) + (dep2)); require(dep1 <= 1000000000000000000000000000000); require(dep2 <= 1000000000000000000000000000000);
        require(address(this).balance >= dep1 + dep2);
        require(dep1 > 0 && dep2 > 0);

        c.deposit{value: dep1}(); if (__ESBMC_reverted()) return;
        c.deposit{value: dep2}(); if (__ESBMC_reverted()) return;

        uint256 balanceBefore = address(c).balance;
        uint256 testBalanceBefore = address(this).balance;
        uint256 creditBefore = dep1 + dep2;

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint256 balanceAfter = address(c).balance;
        uint256 testBalanceAfter = address(this).balance;

        assert(balanceBefore >= creditBefore ? (balanceAfter + creditBefore == balanceBefore && testBalanceAfter == testBalanceBefore + creditBefore && !reverted) : (balanceAfter == balanceBefore && testBalanceAfter == testBalanceBefore && reverted));
    }

    receive() external payable {}
}

