pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 dep1, uint256 dep2) internal {
        dep1 = bound(dep1, 0, 1000000000000000000000000000000);
        dep2 = bound(dep2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= dep1 + dep2);
        vm.assume(dep1 > 0 && dep2 > 0);
        try c.deposit{value: dep1}() {} catch { return; }
        try c.deposit{value: dep2}() {} catch { return; }
        uint256 balanceBefore = address(c).balance;
        uint256 testBalanceBefore = address(this).balance;
        uint256 creditBefore = dep1 + dep2;
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        uint256 balanceAfter = address(c).balance;
        uint256 testBalanceAfter = address(this).balance;
        assertTrue(balanceBefore >= creditBefore ? (balanceAfter + creditBefore == balanceBefore && testBalanceAfter == testBalanceBefore + creditBefore && !reverted) : (balanceAfter == balanceBefore && testBalanceAfter == testBalanceBefore && reverted));
    }

    function testFuzz_run(uint256 dep1, uint256 dep2) public {
        _run(dep1, dep2);
    }

    receive() external payable {}
}
